def confidence_size_multiplier(prob, threshold=0.55, cap_prob=0.75):
    conviction = max(prob, 1 - prob)  # distance from 50/50, works for either class
    if conviction < threshold:
        return 0.0  # below threshold: no trade at all, per Lesson 2's signal rule
    scaled = (conviction - threshold) / (cap_prob - threshold)
    return min(1.0, max(0.0, scaled))  # a multiplier between 0 and 1
